      if (!reader.result) return
      createImage(`chart-${tradeId}-${images.length}`, reader.result.toString())
    }
    reader.readAsDataURL(file)
  }

  const removeGalleryImage = (imageId: string) => {
    if (!tradeId || !diaryToken) {
