    const pairs = [];

    for (const rank of Object.keys(ranks)) {
        if (ranks[rank] >= 2) {
            pairs.push(rank);
        }
    }

    if (pairs.length < 2 || Object.keys(ranks).length > 2) {
        return [];
    }

    return [...new Set(pairs)].sort().reverse();
