    html += "<tr>";
    html += `<td>${players[i]}</td>`;
    html += `<td>${stats[players[i]]}</td>`;
    html += "</tr>";
  }

  // Output other values column
  //html += "<tr><td colspan=2>Other Values:</td></tr>";

