def is_prime(n):
    if n < 2:
        return False
    for i in range(2, n//2 + 1):
        if n % i == 0:
            return False
    return True

def sum_of_primes(arr):
    total = 0
    for num in arr:
        if is_prime(num):
            total += num
    return total

